"""Fifty individually reviewed CTB units: sanctions, proceedings and criminal introduction."""
import copy,json,sys
from pathlib import Path
p=Path(sys.argv[1]);old=json.loads((p/'batch-06-existing.json').read_text());expected={r['unit']['unit_key']:r for r in old};rows={}
CTB='https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm'
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
L2020='https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2020/lei/l14071.htm'
L2021='https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14229.htm'
L2023='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14599.htm'
L15428='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15428.htm'
R1020='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/Resolucao10202025.pdf'
R1025='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/resolucao10252026c.pdf'
R1031='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/resolucao10312026.pdf'
R772='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/resolucao7722019.pdf'
D277='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/deliberacoes/Deliberacao2772026.pdf'
STF486='https://noticias.stf.jus.br/postsnoticias/suspensao-de-cnh-de-motorista-profissional-condenado-por-homicidio-culposo-por-acidente-de-transito-e-constitucional/'
def add(n,case,variation,q1,q2,term,meaning,**patch):
 key='art-'+str(n);e=copy.deepcopy(expected[key]['explanation']);data={k:e[k] for k in ['simples','pontos','atencao','exemplo','prova','termos','remissoes']}
 data.update(exemplo=case+' Variação: '+variation,prova=[q1,q2],termos=[dict(termo=term,significado=meaning)])
 data['pontos']+=patch.pop('extra_points',[]);data['atencao']+=patch.pop('notes',[]);data['remissoes']=list(dict.fromkeys([CTB,*data['remissoes'],*patch.pop('sources',[])]));data.update(patch);rows[key]=data
add(248,'Ônibus transporta carga excedente em desacordo com o regime do art. 109. Resposta: grave, multa e retenção para transbordo.', 'Transportar carga nos limites e condições autorizados não é proibido universalmente apenas por ser veículo de passageiros.', 'Qualquer encomenda em ônibus é automaticamente infração do 248? Não. A descrição exige carga excedente em desacordo com o art. 109 e suas normas.', 'A medida é sempre remover ao depósito sem oportunidade de regularizar? Não. A medida textual é retenção para transbordo, integrada aos procedimentos pertinentes.', 'Carga excedente','Quantidade/condição irregular no regime do veículo de passageiros, não toda carga.',notes=['Conferir art. 109 e norma adequada; não inventar quantidade universal no art. 248.'])
add(249,'À noite, veículo parado para desembarque apaga as luzes de posição. Resposta: o artigo descreve infração média.', 'O dever de posição na parada não substitui luz baixa nas hipóteses de veículo em movimento do art. 250.', 'O artigo trata exclusivamente de veículo em movimento? Não. Refere-se a PARADO, à noite, para embarque/desembarque ou carga/descarga.', 'A classe é grave apenas por ser à noite? Não. O art. 249 fixa MÉDIA, com multa, sem classificar por gravidade presumida do contexto.', 'Luz de posição','Iluminação pertinente ao veículo parado no recorte, distinta de farol baixo de circulação.',notes=['Não confundir luz de posição e luz baixa; manter os recortes noite e finalidade da parada.'])
add(250,'Carro com DRL entra de dia num túnel sem acender luz baixa. Resposta: DRL não dispensa a hipótese da alínea b.', 'Em rodovia de pista simples fora do urbano, a alínea e distingue veículo sem DRL; motocicleta tem obrigação própria de dia, e porta aberta do coletivo/escolar tem gravidade distinta.', 'Todo uso irregular descrito no art. 250 é média? Não. I/III têm classe média; IV, porta aberta de público coletivo/escolar em movimento, é gravíssima com retenção.', 'DRL elimina luz baixa durante chuva, neblina ou túnel? Não. A exceção relacionada à rodovia sem DRL não elimina as exigências independentes da alínea b.', 'DRL e luz baixa','Equipamentos de funções distintas, sem dispensa universal pela presença de DRL.',notes=['Inciso II revogado não cria obrigação atual. Lei 14.440/2022 acrescentou IV; não tornar média toda hipótese do artigo.'],sources=[L2020])
add(251,'A sinalização regulamentar determina pisca-alerta em certo trecho. Resposta: integrar a hipótese expressa do inciso II, c, e art. 40, V, não afirmar que só emergência permite.', 'Ligar por preferência pessoal para circular devagar, sem hipótese admitida, não se torna automaticamente regular.', 'O texto admite determinação sinalizada de pisca-alerta? Sim. Há previsão no inciso II, c, integrada ao art. 40, V, além das situações de imobilização/emergência.', 'A regra da buzina fora do urbano deve ser copiada para toda troca breve de luzes? Não. Buzina e advertência luminosa têm descrições distintas; integrar art. 40, III.', 'Advertência luminosa','Sinalização por luzes nas hipóteses legais, distinta de uso pessoal irrestrito.',atencao=['Evitar resumo só imobilização ou emergência, ignorando sinalização que determina uso.','As alíneas devem ser integradas ao art. 40; não criar proibição onde ele prevê advertência de risco no sentido contrário.'])
add(252,'Condutor segura ou manuseia o celular ao dirigir. Resposta: parágrafo único, gravíssima; não reduzir a média apenas porque uma mão está fora do volante.', 'Retirar uma mão para mudar marcha ou indicar sinal de braço integra exceções específicas do V, não dispensa para manusear celular.', 'Dirigir descalço é expressamente proibido pelo inciso IV? Não. O inciso trata de calçado que não se firme ou prejudique pedais; não inventar proibição textual de estar descalço, mantendo segurança geral.', 'Qualquer retirada de mão caracteriza gravíssima? Não. Há exceções do V e o agravamento do parágrafo depende de segurar/manusear telefone.', 'Manuseio do celular','Conduta com classe gravíssima específica, distinta de toda direção com uma mão.',notes=['Não presumir incapacidade por deficiência; inciso III exige incapacidade temporária que comprometa segurança.','Cobrar tarifa com veículo em movimento tem inciso VII médio; não trocar atos e classes.'])
add('253-a','Organizador usa veículo deliberadamente para restringir circulação sem autorização. Resposta: distinguir multa de sessenta vezes para organizador e vinte vezes do caput.', 'Pane involuntária que interrompe fluxo não completa por si o elemento deliberadamente; podem existir outros deveres e tipos.', 'O multiplicador do organizador é sessenta vezes sobre os vinte já multiplicados? Não. São fatores do tipo em relação ao valor-base, não multiplicação automática 20 × 60.', 'A descrição exige simplesmente qualquer imobilização involuntária? Não. O caput exige uso deliberado para interromper/restringir/perturbar sem autorização.', 'Bloqueio deliberado','Uso intencional do veículo no recorte do artigo, distinto de toda pane ou interrupção.',extra_points=['§3º: restabelecer circulação de imediato SE POSSÍVEL, não obrigação material sem ressalva.'],notes=['Não presumir culpabilidade de todo participante pela atuação do organizador nem fechar aqui toda controvérsia constitucional sobre manifestação.'])
add(254,'Pedestre usa bordos da pista porque o passeio está inutilizável, atendidas as condições do art. 68. Resposta: não aplicar proibição isolada ignorando a hipótese de circulação permitida.', 'As proibições textuais do 254 permanecem no código, mas o procedimento da Resolução 706/2017 foi revogado pela 772/2019; não ensinar autuação operacional automática por esse regulamento antigo.', 'O texto fixa multa integral de infração leve para pedestre? Não. Prevê 50% do valor de leve; distinguir previsão legal e procedimento exigível para aplicação.', 'A revogação da Resolução 706 revogou automaticamente o art. 254? Não. Revogou o procedimento regulamentar; o dispositivo legal e as garantias do pedestre devem ser integrados.', 'Previsão e aplicação','Comando legal distinto da implantação do procedimento sancionador pertinente.',atencao=['Integrar circulação legítima do art. 68 e hipóteses de permissão; não proibir todo uso dos bordos na ausência de passeio.','Resolução 772/2019 revogou 706/2017. Não certificada implantação atual de procedimento uniforme para autuar pedestres; não criar exercício de multa automática como fato operacional.','Inciso VII e parágrafos vetados não instituem novos deveres.'],sources=[R772])
add(255,'Ciclista está desmontado e empurra a bicicleta no passeio. Resposta: é equiparado ao pedestre pelo art. 68, §1º; não confundir com pedalar de forma agressiva.', 'Pedalar em passeio autorizado ainda exige cuidado; permissão não legitima agressividade.', 'Bicicleta no passeio é sempre infração independentemente de autorização? Não. Integrar art. 59 e equiparação do ciclista desmontado, sem proibição universal.', 'A remissão ao parágrafo único do art. 59 indica texto vigente com conteúdo a inventar? Não. O art. 59 atual não tem esse parágrafo; tratar remissão residual e não fabricar regra.', 'Ciclista desmontado','Pessoa empurrando bicicleta equiparada ao pedestre, diferente da condução montada.',simples='O art. 255 prevê classe média para bicicleta em passeio não permitido ou condução agressiva. Integrar autorização/sinalização do art. 59 e ciclista desmontado equiparado ao pedestre. A remissão a parágrafo único inexistente no art. 59 atual é residual. A medida textual de remoção mediante recibo não autoriza aplicação operacional automática de regulamento revogado.',atencao=['Resolução 706/2017 foi revogada pela 772/2019. Não certificada aqui implantação uniforme de fiscalização sancionadora de ciclistas.','Não gerar exercício apoiado em parágrafo inexistente ou que puna automaticamente empurrar bicicleta como pedestre.'],sources=[R772])
add(257,'Pessoa jurídica não identifica infrator no prazo de trinta dias da notificação. Resposta: o §8º atual prevê nova multa ao proprietário de duas vezes a originária, mantendo esta e garantias de defesa.', 'Para excesso de peso, único remetente e documento declarando menos que o aferido têm §4º; carga de vários embarcadores ou peso declarado acima do limite têm recortes distintos.', 'A multa de não identificação de pessoa jurídica cresce automaticamente pelo número de infrações antigas conforme redação histórica? Não. A Lei 14.229/2021 fixou duas vezes a originária, com defesa e recurso, no §8º atual.', 'Proprietário e condutor sempre respondem juntos por qualquer infração? Não. Separar regularidade do veículo, ato de direção e hipóteses efetivas de solidariedade, sem universalizar o §1º.', 'Identificação do infrator','Apresentação no prazo e forma pertinentes, distinta de punir toda pessoa por vínculo com o veículo.',simples='Responsabilidade depende da obrigação: proprietário pela regularidade/condições do veículo; condutor pelos atos de direção; embarcador/transportador por excessos nos recortes dos §§4º–6º. Sem identificação imediata, principal condutor/proprietário tem trinta dias da notificação para indicar. Pessoa jurídica sem identificação recebe nova multa de duas vezes a originária, mantendo a anterior e garantias. Cadastro de principal condutor requer aceitação; exclusão tem hipóteses próprias.',pontos=['§4º: ÚNICO remetente e peso documental INFERIOR ao aferido, simultaneamente.','§5º: excesso nos eixos ou carga de mais de um embarcador excedendo PBT, transportador.','§6º: peso declarado SUPERIOR ao limite legal, solidariedade transportador/embarcador.','§7º: trinta dias da notificação; principal condutor ou, na ausência, proprietário responde no regime pertinente.','§8º: pessoa jurídica, nova multa DUAS vezes a originária, mantida esta, com defesa/recurso.','§10: principal condutor aceita indicação; §11: exclusão por transferência, requerimento ou outro principal condutor.'],notes=['Não transferir automaticamente toda pontuação a pessoa jurídica nem confundir regularidade do veículo e autoria de direção.'],sources=[L2020,L2021])
add(258,'Infração gravíssima com multiplicador três tem base R$ 293,47. Resposta: três vezes resulta em R$ 880,41, sem transformar pontuação em 21 pontos.', 'Uma multa grave simples usa R$ 195,23; multiplicador depende do tipo específico, não da vontade do fiscal.', 'Toda multa gravíssima tem automaticamente dez vezes o valor? Não. A base é R$ 293,47; agravamento requer fator do artigo aplicável.', 'Multiplicar o valor financeiro multiplica sempre pontos? Não. Multa e pontuação têm regimes diferentes, incluindo exceções do art. 259.', 'Valor-base','Quantia da classe antes de multiplicador legal específico, distinta de número de pontos.',notes=['Valores atuais do texto compilado: 293,47/195,23/130,16/88,38; não antigas UFIR.'])
add(259,'Infração de média do art. 233 não pontua pela exceção do §4º, II. Resposta: a regra geral de quatro pontos não é universal.', 'Infração autossuspensiva tem exceção III: não somar automaticamente sete pontos por ser gravíssima além da suspensão específica.', 'Multa com fator dez gera setenta pontos por esse multiplicador? Não. Pontuação é regime distinto; fatores financeiros não multiplicam sete/cinco/quatro/três.', 'A suspensão específica elimina qualquer consequência administrativa da infração? Não. A exceção é de pontuação, mantendo penalidades e medidas cabíveis.', 'Exceção de pontuação','Situação sem pontos no recorte legal, não dispensa geral de multa ou medida.',atencao=['Não resumir cada infração média sempre quatro pontos: conferir §4º.','A referência ao art. 233-A no rol não cria infração vigente onde o dispositivo não tem comando ativo.','Exceção de passageiros de longa distância tem recorte e regulamentação; não dispensa universal de responsabilidade do condutor.'],sources=[L2020])
add(260,'Veículo de uma UF recebe infração em outra. Resposta: arrecadação/compensação e eventual comunicação ao órgão de licenciamento seguem o artigo e normas do Contran.', 'A circunscrição territorial não elimina a distribuição de competência: não afirmar que qualquer órgão da via autua qualquer tipo sem limite.', 'O artigo manda sempre arrecadar só no órgão do registro do veículo? Não. Regra do caput é órgão com circunscrição da via conforme competência, com compensação entre UFs.', 'Para veículo licenciado no exterior, o §4º ignora reciprocidade? Não. Exige pagamento antes da saída respeitado o princípio de reciprocidade, integrado ao regime aplicável.', 'Compensação interestadual','Acerto de arrecadação entre órgãos, distinto da atribuição da infração.',notes=['Competência, circunscrição e notificação não são sinônimos; integrar exceções legais como art. 165-D.'])
add(261,'Condutor comum soma trinta pontos em doze meses, com uma gravíssima que integra pontuação. Resposta: alcança o limiar de trinta, com aplicação mediante processo e defesa.', 'Condutor com atividade remunerada ao veículo tem limiar quarenta por pontos, mas pode sofrer suspensão específica antes disso; o regime não é imunidade.', 'Todo condutor C/D/E tem automaticamente limiar quarenta só pela categoria? Não. O §5º liga o regime à atividade remunerada ao veículo, não apenas à letra da categoria.', 'Infrações com prazo específico de suspensão recebem sempre o prazo geral de dois a oito meses? Não. O §1º, II, ressalva prazo descrito no tipo e reincidência; não substituir doze meses do art. 165 por faixa geral.', 'Suspensão por pontos','Regime de limiares em doze meses, distinto de suspensão própria de uma infração.',pontos=['20 com DUAS OU MAIS gravíssimas na pontuação; 30 com UMA; 40 com NENHUMA.','§5º: atividade remunerada, quarenta independentemente da natureza, só para suspensão POR PONTOS.','§1º, I: 6 meses a 1 ano; reincidência até doze meses: 8 meses a 2 anos.','§1º, II: 2 a 8 meses, ressalvado prazo próprio; reincidência: 8 a 18 meses, com integração ao art. 263, II.','EAR: curso preventivo facultativo com trinta pontos; conclusão elimina pontos, nova opção só após doze meses.','§10: processo de suspensão específica concomitante ao da multa pelo órgão aplicador, conforme norma.'],atencao=['Não contar gravíssimas sem pontuação automaticamente nos limiares; integrar art. 259, §4º.','Suspensão/cassação exigem processo do art. 265. Curso preventivo não elimina automaticamente infração autossuspensiva.'],sources=[L2020,R1020])
add(263,'Condutor dirige durante suspensão regularmente imposta. Resposta: pode incidir cassação, mediante processo de competência e defesa, não mero recolhimento físico.', 'Após dois anos da cassação, requerer reabilitação não equivale a recuperar automaticamente a habilitação; exige exames.', 'O §2º autoriza retorno automático a dirigir ao completar dois anos? Não. Permite requerer reabilitação e exige os exames necessários conforme Contran.', 'Toda reincidência de qualquer gravíssima em doze meses gera inciso II? Não. O inciso enumera infrações específicas; não ampliar o rol nem confundir cassação, suspensão e cancelamento.', 'Cassação e reabilitação','Perda do documento com posterior requerimento/exames, distinta de suspensão temporária.',notes=['§1º: cancelamento por irregularidade de expedição é hipótese distinta. Não afirmar toda condenação causa cassação automática sem art. 160 e procedimento pertinente.'],sources=[R1020])
add(265,'A autoridade competente impõe suspensão por decisão motivada após processo com defesa. Resposta: corresponde às garantias do artigo.', 'A gravidade da infração não dispensa motivação nem transforma toda suspensão definitiva em punição sumária no local.', 'A autoridade pode impor cassação definitiva sem assegurar defesa por ser sanção grave? Não. O artigo exige decisão fundamentada e processo administrativo com amplo direito de defesa.', 'Suspensão administrativa definitiva e cautelar judicial são idênticas? Não. Têm fundamentos e procedimentos diferentes, com dispositivos próprios.', 'Decisão fundamentada','Ato que explicita razões no procedimento competente e preserva defesa.',notes=['Distinguir processo administrativo e medidas judiciais dos arts. 278-A/294.'])
add(266,'Condutor avança vermelho e deixa de usar cinto na mesma ocasião. Resposta: são infrações distintas e podem receber penalidades cumulativas.', 'O mesmo fato descrito alternativamente por tipo geral e específico não deve gerar soma cega: examinar enquadramento e vedação de duplicidade.', 'O artigo manda escolher sempre apenas a infração mais grave de duas condutas distintas? Não. Prevê cumulação das respectivas penalidades quando há duas ou mais infrações simultâneas.', 'A cumulação permite duplicar punição pelo mesmo fato sem análise? Não. Antes é preciso identificar infrações efetivamente distintas; não presumir que toda sobreposição de descrições autoriza duplicidade.', 'Pluralidade de infrações','Duas ou mais infrações reais, distinta de duplicar enquadramentos do mesmo fato.',atencao=['Não manter resumo cumulativas sem absorção como regra automática para todo conflito de tipos; analisar condutas e enquadramento.'])
add(267,'Infrator comete leve punível com multa e não tem nenhuma outra infração nos últimos doze meses. Resposta: a redação atual manda advertência por escrito.', 'Ter cometido outra infração diferente nesse período pode afastar requisito; não exigir apenas ausência de reincidência no mesmo tipo como na regra antiga.', 'A autoridade mantém discricionariedade livre para negar advertência apesar dos requisitos? Não. O texto atual usa DEVERÁ e delimita natureza leve/média e histórico sem outra infração.', 'Basta não repetir a mesma infração para atender ao histórico? Não. A redação exige nenhuma OUTRA infração nos últimos doze meses, não só ausência de reincidência específica.', 'Advertência obrigatória','Sanção escrita imposta quando preenchidos os requisitos atuais, sem critério antigo facultativo.',notes=['Lei 14.071/2020: §§1º/2º revogados e regra atual obrigatória; não recuperar regime antigo.'],sources=[L2020])
add(268,'Condutor contribuiu para sinistro grave. Resposta: inciso III prevê reciclagem e o parágrafo avaliação psicológica adicional, sem depender de processo judicial.', 'Só estar envolvido sem contribuição demonstrada não é suficiente para presumir esse inciso; hipótese de risco do V também precisa ser constatada.', 'Todo envolvido em sinistro grave recebe III por automatismo? Não. O inciso exige que HAJA CONTRIBUÍDO, não apenas envolvimento.', 'Toda reciclagem por suspensão do inciso II exige avaliação psicológica adicional por este parágrafo? Não. A previsão adicional enumera III, IV e V, sem incluir indiscriminadamente II.', 'Reciclagem por hipótese','Curso com fundamento específico, distinto de responsabilidade presumida no sinistro.',notes=['Não restaurar incisos I/VI revogados; formação regulamentar atual na Resolução 1020/2025.'],sources=[R1020])
add('268-a','Condutor inscrito no RNPC chega ao fim da validade. Resposta: a Lei 15.428/2026 prevê renovação automática no recorte, mas mantém exames de aptidão física e mental.', 'Não ter infração pontuável e aderir ao RNPC não elimina por si todo exame nem concede benefício fiscal automaticamente sem lei do ente.', 'O RNPC atual dispensa os exames físicos e mentais na renovação? Não. O §7º da Lei 15.428 excepciona expressamente esses exames da dispensa de procedimentos.', 'Inscrição depende de nova autorização para cada anotação posterior? Não. A abertura exige autorização prévia e expressa; depois, §3º admite anotações sem nova autorização/comunicação.', 'RNPC','Registro positivo com consentimento de abertura, requisitos e exclusões próprias.',simples='RNPC cadastra quem não teve infração pontuável em doze meses, com consentimento expresso de abertura e atualização mensal. Anotações posteriores têm regime próprio; exclusão por pedido, pontos, suspensão, cassação/vencimento acima de trinta dias ou pena privativa de liberdade. Benefícios fiscais/tarifários dependem de lei específica. §7º da Lei 15.428/2026: renovação automática na hipótese, mantendo EXAMES DE APTIDÃO FÍSICA E MENTAL; não usar a dispensa integral antiga da MP 1327.',extra_points=['Lei 15.428 publicada/vigente em 5/6/2026, conversão da MP 1327/2025.','Consentimento para abertura não se confunde com consentimento para cada anotação posterior.','§8º/incisos sem corpo ativo após retirada de redação histórica não instituem requisitos a inventar.'],atencao=['Não ensinar dispensa total de exame médico pela redação anterior da MP convertida.','Consulta por cidadãos depende de regulamentação e finalidade; não acesso indiscriminado a dados médicos.','Não certificada aqui toda operação do serviço de renovação automática ou benefício de cada ente.'],sources=[L15428])
add(269,'A medida envolve documento digital. Resposta: §5º prevê registro no Renach/Renavam conforme o caso, não apreensão física de arquivo como se fosse cartão.', 'Medida administrativa complementa a sanção, mas não significa que todo caso exige aplicar todas as medidas do rol.', 'Retenção e multa são sempre a mesma espécie de consequência? Não. A retenção é medida administrativa complementar; penalidade tem regime e pressupostos próprios.', 'O rol autoriza recolher CNH em toda abordagem de álcool ignorando norma atual? Não. Integrar procedimento específico da Resolução 1031, art. 12, e competência/circunscrição.', 'Medida administrativa','Providência complementar de segurança/regularização, distinta de pena autônoma.',extra_points=['§5º: documentos digitais, registro nos sistemas pertinentes.','§3º: CNH, PPD e ACC, três documentos de habilitação.','§4º: animais recolhidos, aplicar 271/328 no que couber.'],notes=['Não aplicar todas as medidas a qualquer infração sem base específica; prioridade à vida e incolumidade.'],sources=[R1031])
add(270,'Falha não é sanável no local, mas o veículo oferece segurança e há habilitado regular. Resposta: examinar liberação com prazo razoável de até trinta dias e procedimento do §2º.', 'Sem segurança ou sem condutor habilitado, não ensinar essa liberação como direito automático; §4º prevê remoção ao depósito sem condutor.', 'O prazo do §2º da retenção é sempre quinze dias? Não. É razoável e não superior a TRINTA; quinze aparece em hipótese distinta do art. 271, §9º-A.', 'Coletivo com passageiros é sempre liberado mesmo inseguro? Não. O §5º deixa a avaliação ao agente e exige condições de segurança, também para perigoso/perecível.', 'Retenção com regularização','Providência com hipóteses de saneamento/liberação, distinta de remoção e seus prazos.',notes=['Sem regularização no prazo: restrição no Renavam e recolhimento conforme §§6º/7º; não dispensa permanente.','Documento digital: integrar registro do art. 269, §5º.'])
add(271,'Irregularidade é sanada no local. Resposta: §9º impede remoção nessa hipótese, sem dizer que toda multa desaparece.', 'Não sanável, mas seguro: §9º-A pode admitir até quinze dias, com exceções §9º-B para não registrado/licenciado e transporte remunerado irregular.', 'O prazo de quinze dias se aplica sem exceção ao veículo não licenciado? Não. §9º-B exclui art. 230, V, e art. 231, VIII, da liberação do §9º-A.', 'Toda diária de depósito pode ser cobrada indefinidamente por esse regime? Não. §10 limita despesas correspondentes à permanência a seis meses, integrado à norma atual.', 'Remoção e restituição','Regime com notificações, segurança, débitos exigíveis e exceções específicas.',simples='Remoção ao depósito tem hipóteses, notificações e restituição regular. Não cabe se sanar no local; liberação segura com até quinze dias do §9º-A exclui 230,V e 231,VIII. Reparo impossível no depósito pode permitir transporte para reparo autorizado. Despesas de estada são limitadas a seis meses; cobrança de multas deve integrar exigibilidade e defesa, inclusive art. 284, §3º. Abuso/recolhimento indevido pode gerar devolução pelo ente público. Resolução 1025/2026 substituiu 623/2016, com regras e transição do Sivec.',pontos=['Ausente proprietário/condutor: expedir notificação em dez dias, com regime de meios pertinente.','§9º-A: até QUINZE dias se seguro; §9º-B: exceções 230,V e 231,VIII.','§3º: saída para reparo em forma TRANSPORTADA, mediante autorização.','§10: limite de SEIS MESES de despesas, não obrigação de manter custódia sempre seis meses.','§13: devolução por recolhimento indevido ou abuso comprovado, administrativa/judicialmente.','Resolução 1025 vigente desde 30/6/2026; art. 15, §3º, prevê SNE exclusivo a partir de 1º/1/2027, não já exclusivo em 13/10/2026.'],atencao=['Não condicionar regularidade a multa inexigível ou processo administrativo pendente ignorando art. 284, §3º.','Resolução 1025, art. 17: guarda monitorada é possibilidade autorizada com requisitos, não direito automático. Art. 44: obrigações dependentes do Sivec têm transição; não certificada implantação plena do sistema.','Art. 23 da resolução: reparo fora do centro, transporte autorizado e reapresentação até sessenta dias; não confundir com quinze/trinta dos regimes de liberação na via.'],sources=[R1025])
add(272,'Há suspeita de inautenticidade da CNH e a autoridade recolhe conforme competência. Resposta: deve emitir recibo; suspeita não equivale a condenação penal automática.', 'No documento digital, integrar registro do art. 269, §5º, sem imaginar recolhimento físico obrigatório de arquivo.', 'Só há recolhimento quando já existe sentença penal de falsificação? Não. O artigo inclui SUSPEITA de inautenticidade/adulteração, além de outros casos legais.', 'Recolher CNH prova automaticamente falsidade e dispensa processo? Não. A medida e a suspeita não eliminam análise, defesa ou requisitos de eventual crime.', 'Recolhimento documental','Medida com recibo e base legal, distinta de cassação definitiva.',notes=['Integrar documento digital e regras atuais; não converter medida em pena sem processo.'])
add(273,'Veículo foi alienado e não houve transferência em trinta dias. Resposta: hipótese do inciso II de recolhimento do CRV mediante recibo.', 'O prazo de sessenta dias do antigo proprietário para comunicar tem outra finalidade e não substitui o limiar deste artigo.', 'O documento descrito é a CNH do condutor? Não. É Certificado de Registro do veículo; não trocar identidade e finalidade dos documentos.', 'A transferência ganha sessenta dias automaticamente por referência ao vendedor? Não. O artigo usa trinta na hipótese de alienação; comunicação do vendedor é distinta.', 'CRV recolhido','Documento registral sujeito à medida do artigo, diferente da habilitação.',notes=['Documento digital: integrar art. 269, §5º; suspeita não dispensa recibo/procedimento.'])
add(274,'No regime de retenção, a irregularidade não pode ser sanada no local. Resposta: o inciso III prevê recolhimento do certificado anual com recibo, integrado aos procedimentos.', 'Vencimento da CNH não é o mesmo de licenciamento do veículo; não trocar o inciso II por habilitação.', 'O inciso II descreve CNH vencida há mais de trinta dias? Não. Trata do prazo de LICENCIAMENTO; CNH vencida é outro documento e hipótese.', 'Digitalização elimina toda medida administrativa do certificado? Não. O art. 269, §5º, adapta as medidas a registro no sistema pertinente.', 'Certificado anual','Documento do licenciamento do veículo, distinto de CRV e CNH.',notes=['Integrar arts. 270/271 e forma digital, sem exigir apreensão física de arquivo.'])
add(275,'Caminhão não consegue fazer transbordo imediato do excesso. Resposta: parágrafo prevê depósito e liberação após regularizar e pagar despesas pertinentes.', 'Pagar a multa não torna livre continuar com excesso sem observar a legislação de peso e tolerância.', 'O custo do transbordo é automaticamente do órgão fiscalizador? Não. O caput o atribui ao proprietário do veículo, sem prejuízo da multa cabível.', 'Pagamento da multa sozinho elimina a condição de descarregar excedente? Não. Transbordo regularizador é condição de prosseguir, integrado ao regime aplicável.', 'Transbordo do excedente','Regularização de carga para continuar, distinta de só quitar a sanção financeira.',notes=['Confrontar tolerância e critérios legais: não descarregar quantitativo arbitrário sem aferição pertinente.'])
add(276,'Etilômetro registra resultado baixo. Resposta: tolerância zero legal não elimina o desconto do erro máximo e os requisitos metrológicos para autuar.', 'Pré-teste passivo indicativo não pode fundamentar sozinho a infração pela Resolução 1031, apesar da política de tolerância zero.', 'Qualquer número bruto exibido torna a autuação automaticamente válida? Não. O parágrafo exige margem de tolerância metrológica e a Resolução 1031 distingue medição e valor considerado.', 'Margem do aparelho é autorização para consumir certa dose e dirigir? Não. É tratamento de incerteza de medição, distinto de tolerância legal ao consumo.', 'Erro metrológico','Incerteza descontada na aferição, não licença para beber uma quantidade segura.',simples='A política legal é de qualquer concentração, mas a aplicação por aparelho deve observar margem metrológica, prova e procedimento. Resolução 1031/2026 substituiu 432/2013 e distingue pré-teste indicativo, medição realizada e valor considerado. Não ensinar autuação automática de todo número bruto nem dose autorizada de bebida.',atencao=['Não confundir tolerância zero jurídica e incerteza técnica do aparelho.','Não calcular por conta própria dose ou tempo seguro para dirigir; o exercício trata de requisitos legais de aferição.'],sources=[R1031])
add(277,'O agente constata ao menos dois sinais em conjunto, devidamente registrados conforme a Resolução 1031. Resposta: há regime de prova distinto de exigir exclusivamente bafômetro.', 'O texto admite imagem/vídeo e outros meios, mas não presumir que qualquer foto ou um sinal isolado satisfaz todo requisito atual de constatação.', 'O bafômetro é o único meio legal de caracterizar influência? Não. O §2º admite outros meios e sinais conforme regulamentação, que deve ser observada.', 'Recusa sozinha constitui automaticamente crime do art. 306? Não. Tem hipótese administrativa própria; crime depende de elementos/provas distintos.', 'Constatação regulamentada','Prova por meios admitidos e critérios técnicos atuais, não impressão isolada do agente.',atencao=['Resolução 1031/2026: pelo menos dois sinais em conjunto, registrados; pré-teste só indicativo.','Em 13/10, procedimentos do ato já vigentes; fichas alteradas do Manual têm vacância até 17/10/2026.','Recusa e sinais suficientes têm distinção regulamentar de enquadramento nos arts. 165/165-A.'],sources=[R1031])
add(278,'Motorista evade pesagem obrigatória. Resposta: penalidade do art. 209 não dispensa retornar ao ponto de evasão para pesagem.', 'A expressão apreensão do veículo no parágrafo deve ser integrada ao regime atual; não restaurar pena autônoma revogada de 2016.', 'Pagar a multa permite não voltar a pesar? Não. O caput reúne penalidade e obrigação de retorno ao ponto para a pesagem obrigatória.', 'Toda fuga administrativa é automaticamente bloqueio policial do art. 210? Não. Distinguir caput de pesagem e hipótese policial do parágrafo, além de regime atual de medidas.', 'Retorno à pesagem','Dever regularizador que persiste além da consequência financeira.',atencao=['Não ensinar apreensão como penalidade autônoma atual pela remissão residual; distinguir remoção/recolhimento e eventual medida judicial/policial com fundamento próprio.'])
add('278-a','Condutor usa veículo no contrabando e tem condenação transitada em julgado. Resposta: analisar cassação/proibição de obter por cinco anos, com regime e requisitos próprios.', 'Prisão em flagrante não produz automaticamente a consequência definitiva do caput; cautelar do §2º exige decisão motivada, necessidade e integração processual.', 'Flagrante sozinho equivale ao trânsito em julgado exigido para consequência definitiva? Não. Caput e §2º tratam de hipóteses e natureza diferentes.', 'O rol inclui qualquer condenação patrimonial independentemente do uso do veículo? Não. Especifica receptação, descaminho e contrabando com utilização do veículo, sem ampliação universal.', 'Consequência definitiva e cautelar','Regimes distintos de trânsito em julgado e medida processual motivada.',atencao=['A referência de ofício no §2º deve ser confrontada com CPP 282, §2º, sistema acusatório e jurisprudência aplicável. Não ensinar autorização automática em qualquer fase sem integração.','Não certificada aqui decisão específica que encerre todas as controvérsias constitucionais/processuais do artigo. Exercícios não afirmam imposição de ofício irrestrita.'],sources=[CPP])
add(279,'Sinistro com vítima envolve registrador de velocidade/tempo. Resposta: somente o perito oficial encarregado retira disco/unidade armazenadora no recorte do artigo.', 'Não é toda pessoa que trabalha como fiscal ou motorista que recebe essa atribuição; preservar integridade da prova.', 'O condutor pode retirar o disco por preferência pessoal para levar ao perito? Não. O artigo reserva retirada ao perito oficial encarregado do levantamento.', 'O artigo impõe essa mesma exclusividade em toda hipótese sem sinistro/vítima? Não. O recorte descrito é sinistro COM VÍTIMA e veículo equipado, sem ampliar por automatismo.', 'Unidade do registrador','Suporte de dados cuja retirada é reservada no recorte pericial específico.',notes=['Lei 14.599/2023 atualizou terminologia para sinistro, sem dispensar integridade da prova.'])
add('279-a','Veículo sinistrado fica sem responsável no local. Resposta: o §1º prevê remoção no regime pertinente, que não exige necessariamente outra infração.', 'Só estar estacionado por algum tempo não prova abandono; examinar estado e regulamentação em vez de remover qualquer veículo regular.', 'A existência de infração autônoma é sempre pressuposto da remoção do artigo? Não. O caput admite abandono/sinistrado independentemente de infração, nos termos regulamentares.', 'O §1º autoriza tratar todo sinistrado como sem responsável mesmo com ele presente? Não. O recorte é ausência de responsável no local; outras remoções precisam de fundamento próprio.', 'Remoção não sancionatória','Providência por abandono/sinistro nos requisitos, distinta de presumir infração.',notes=['Resolução 1025/2026 integra remoção/custódia/leilão; não automatizar leilão ou baixa por simples remoção.'],sources=[R1025])
add(280,'Autuação por equipamento não tem assinatura do motorista porque não houve abordagem. Resposta: assinatura e prontuário têm sempre que possível, não nulidade automática pela ausência.', 'A exceção do §6º para veículos especiais não elimina dever geral de trânsito seguro nem libera qualquer uso particular por categoria do veículo.', 'Assinatura do infrator é requisito sempre obrigatório em qualquer autuação? Não. Inciso VI usa sempre que possível; comprovação por equipamento e ausência de flagrante têm regime próprio.', 'O §6º declara imunidade a qualquer crime ou toda infração de qualquer condutor policial? Não. O recorte textual é circulação, parada e estacionamento dos veículos destinados às funções indicadas, integrado a segurança e finalidade.',extra_points=['§6º: veículos de socorro, polícia, fiscalização/operação e ambulâncias, ainda que sem identificação ostensiva; não ampliar a toda conduta ou veículo particular.'],term='Auto de infração',meaning='Registro de constatação com campos e requisitos próprios, distinto da decisão final sancionadora.',notes=['Não substituir finalidade/condições por simples etiqueta do veículo. Confrontar art. 29 e art. 1º, §5º.'])
add(281,'Notificação da autuação não é expedida em trinta dias no regime ordinário. Resposta: art. 281, §1º, II, prevê arquivamento, distinguindo expedição de recebimento.', 'Suspensão/cassação têm marco de instauração do processo no §2º; não contar todo prazo indiscriminadamente da data da direção.', 'Receber depois de trinta dias sempre prova expedição tardia? Não. O tipo de controle é EXPEDIÇÃO; recepção e envio não são datas necessariamente idênticas.', 'O marco do §2º é sempre a data da infração para suspensão/cassação? Não. É a instauração do processo destinado às penalidades, integrado aos regimes especiais.', 'Expedição da notificação','Ato de envio distinto do recebimento e do prazo de defesa posterior.',atencao=['Não usar exemplo sem notificação em trinta dias para confundir expedição e recepção.','Regime de free flow 2026 tem transição e marco próprio pelo ato aprovado; não aplicar prazo ordinário sem conferir hipótese.'],sources=[D277])
add('281-a','Notificação indica só quinze dias para defesa prévia. Resposta: viola o mínimo legal de trinta dias no regime descrito.', 'Trinta do mínimo defensivo não é o mesmo prazo máximo de expedir a autuação do art. 281.', 'A norma permite qualquer prazo inferior a trinta por conveniência administrativa? Não. Estabelece prazo de defesa NÃO INFERIOR a trinta, contado da expedição.', 'Trinta dias de defesa e trinta de expedição possuem mesma natureza/marco? Não. Um é mínimo para defesa; outro é máximo de envio no regime ordinário, com marcos pertinentes.', 'Prazo mínimo defensivo','Tempo assegurado para defesa, distinto de prazo máximo de expedição.',notes=['Se auto vale como notificação, deve também conter prazo defensivo.'])
add('282-a','A informação entra no sistema eletrônico e a mensagem correspondente é enviada. Resposta: o §2º prevê considerar notificado após trinta dias desses atos.', 'Ter apenas criado informação sem enviar mensagem não deve ser equiparado automaticamente à condição completa.', 'O §2º usa inclusão OU envio alternativos? Não. A redação exige inclusão da informação E envio da mensagem, sem apagar um dos atos.', 'A oferta de opção eletrônica já significa exclusiva modalidade obrigatória para todo ato em outubro/2026? Não. Distinguir oferta, adesão e transições específicas da legislação, sem antecipar regra de 2027.', 'Notificação eletrônica','Comunicação com inclusão/envio e requisitos do sistema, distinta de mensagem informal.',notes=['Sistema certificado e coordenado pelo máximo executivo federal; cadastro atualizado permanece exigido.','Resolução 1025, art. 15, §3º, prevê exclusividade de SNE da remoção a partir de 1º/1/2027: não antecipar em 13/10/2026 nem afirmar toda modalidade já exclusiva.'],sources=[R1025])
add(284,'Multa de R$ 100 paga pela regra ordinária até vencimento custa R$ 80. Resposta: pagar 80% significa DESCONTO DE 20%, não desconto de 80%.', 'No regime do §1º, pagamento de 60% significa desconto de 40% e exige reconhecimento, ausência de defesa/recurso e adesão anterior ao envio da autuação.', 'Pagar 80% e pagar 60% equivalem aos mesmos requisitos de renúncia? Não. A opção de 60% tem condições do §1º; pagamento ordinário não implica por si renúncia, ressalvado esse regime.', 'A falta de adesão do órgão ao SNE sempre impede os 40% de desconto? Não. O §6º concede se o infrator cumpre os requisitos, mesmo sem adesão do órgão aplicador.', 'Percentual pago','Parte do valor a recolher, diferente do percentual de desconto obtido.',simples='Até vencimento, pagamento por 80% do valor: desconto de 20%. SNE com condições do §1º: pagamento por 60%, desconto de 40%, reconhecendo infração e sem defesa/recurso, com adesão anterior ao envio da autuação. Pagamento comum não é renúncia automática. Antes de encerrar instância administrativa, sem cobrança moratória/restrição do §3º. Após, mora segue Selic e 1% no mês do pagamento. Plataforma deve permitir defesa/recurso de quem não reconhece; órgão não aderente não impede benefício se usuário atende requisitos.',pontos=['80% PAGO = 20% de desconto; 60% PAGO = 40% de desconto.','§1º: adesão antes do envio, reconhecimento e opção sem defesa/recurso, até vencimento; não desconto irrestrito.','§2º: pagamento não renuncia por si ao questionamento, ressalvado §1º.','§3º: sem mora/restrição, inclusive licenciamento/transferência, antes de encerrada instância administrativa.','§5º: campo de defesa/recurso; §6º: órgão não aderente não impede o desconto condicionado.'],atencao=['Não repetir exercício dizendo desconto é 80%; 80% é valor pago.','Não considerar todo pagamento reconhecimento com encerramento; art. 290, III, tem elementos adicionais.'],sources=[L2023])
add(285,'Recurso tempestivo e de parte legítima contra penalidade tem efeito suspensivo. Resposta: não recuperar a regra antiga de ausência desse efeito.', 'Recurso intempestivo é arquivado; parte ilegítima não recebe o mesmo efeito, mesmo protocolando em dia.', 'Remessa à JARI em dez dias conta do recebimento pela JARI? Não. §2º conta da INTERPOSIÇÃO perante autoridade que impôs a penalidade; julgamento tem marco próprio.', 'O prazo de vinte e quatro meses já era aplicado indistintamente por todo texto histórico de 2021? Não. Lei 14.229 diferiu as alterações de julgamento para 1º/1/2024; fatos/transições precisam do marco correto.',extra_points=['§6º: vinte e quatro meses do recebimento pelo órgão JULGADOR.','§4º: não exigir documentos emitidos pelo próprio órgão autuador para admissibilidade; não dispensa de toda documentação.'],term='Efeito suspensivo',meaning='Suspensão dos efeitos no recurso admissível, distinta de arquivar recurso intempestivo.',notes=['Não confundir prazo de remessa, interposição e julgamento.'],sources=[L2021])
add(286,'O interessado recorre dentro do prazo sem pagar a multa. Resposta: o caput permite recurso sem recolhimento do valor.', 'Se pagou e ganha o recurso, a importância deve ser devolvida com correção no índice legal pertinente; a menção histórica à UFIR não autoriza inventar taxa.', 'Pagar é condição de admissibilidade do recurso do 286? Não. O caput expressamente permite interposição no prazo legal sem recolher a multa.', 'O parágrafo único atual do art. 284 contém exatamente a regra referida no §1º? Não. A estrutura atual tem parágrafos numerados; a remissão antiga deve ser integrada ao regime vigente, não a texto inexistente.', 'Pagamento e recurso','Faculdades distintas no regime ordinário, com devolução se a penalidade for afastada.',atencao=['Não recuperar parágrafo único inexistente do 284 nem usar UFIR como indexador atual universal.','Regime de 60% condicionado no art. 284, §1º, tem opção sem defesa/recurso; distinguir pagamento ordinário.'])
add(287,'Infrator autuado em local diverso do licenciamento apresenta recurso no órgão de residência/domicílio. Resposta: é faculdade expressa, e o receptor o remete de pronto ao órgão aplicador.', 'Protocolar fora não cria prazo novo ilimitado nem muda o órgão competente para julgar o mérito.', 'A faculdade exige sempre deslocar-se à localidade da infração? Não. O artigo admite apresentação no órgão do domicílio/residência do infrator na hipótese descrita.', 'A autoridade receptora necessariamente passa a julgar a penalidade? Não. O parágrafo manda remetê-lo à autoridade que impôs, com documentos pertinentes.', 'Protocolo facilitado','Local alternativo de apresentação, distinto da competência de julgamento.',notes=['Manter prazo e requisitos de recurso, sem inventar extensão por remessa entre órgãos.'])
add(288,'A JARI nega provimento e o responsável recorre em trinta dias da publicação/notificação. Resposta: corresponde à legitimidade do §1º.', 'Se dá provimento, a autoridade que impôs a penalidade pode recorrer; não limitar recurso sempre ao infrator.', 'Somente o infrator pode recorrer de qualquer resultado da JARI? Não. §1º distingue não provimento pelo responsável e provimento pela autoridade aplicadora.', 'O §2º revogado ainda exige o antigo depósito para recorrer? Não. Não recuperar requisito revogado; art. 286 também assegura recurso sem recolhimento.', 'Segunda instância','Recurso com legitimidade conforme resultado, distinto de defesa prévia.',notes=['Prazo trinta da publicação OU notificação, não da primeira autuação.'])
add(289,'Penalidade municipal é revista na instância do Cetran. Resposta: não atribuir todo recurso ao Contran.', 'Na União com só uma JARI, o parágrafo prevê julgamento por seus membros, exceção à composição ordinária especial.', 'Toda penalidade federal é julgada necessariamente pelo Contran? Não. O inciso I atual prevê colegiado especial e hipóteses do parágrafo, com alíneas antigas revogadas.', 'O prazo de vinte e quatro meses conta da primeira infração? Não. Conta do recebimento do recurso pelo órgão julgador, conforme caput.',extra_points=['Uma JARI: seus membros; novos colegiados quando necessário: presidente da que apreciou e mais dois presidentes.','Prazo atual de vinte e quatro meses: produção normativa da Lei 14.229 para 1º/1/2024.'],term='Colegiado especial',meaning='Instância de revisão federal na composição legal atual, diferente de Contran universal.',notes=['Distinguir Cetran para Estados/Municípios e Contrandife no DF; não restaurar alíneas revogadas.'],sources=[L2021])
add('289-a','Recurso sujeito à regra atual não é julgado no prazo de vinte e quatro meses do recebimento pelo órgão julgador. Resposta: o artigo prevê prescrição da pretensão punitiva.', 'Não contar automaticamente da infração ou aplicar o regime novo a todo processo histórico sem análise temporal.', 'O dispositivo disciplina decadência pela falta de expedir autuação em trinta dias? Não. Aqui é prescrição por atraso de JULGAMENTO de recurso; art. 281 tem outra hipótese.', 'O prazo começou universalmente em 2021 pela simples edição da Lei 14.229? Não. A vigência destas disposições foi diferida para 1º/1/2024; análise temporal é necessária.', 'Prescrição recursal','Consequência de atraso no julgamento nos marcos legais, distinta de decadência de notificação.',notes=['Não usar exemplo todo atraso faz multa prescrever sem marco, prazo e regime temporal.'],sources=[L2021])
add(290,'Infrator paga reconhecendo infração e requer encerramento sem defesa/recurso. Resposta: a combinação de elementos integra o inciso III.', 'Pagar pelo regime ordinário para evitar mora e manter recurso não é automaticamente a mesma hipótese de encerramento.', 'Todo pagamento de multa encerra por si a instância administrativa? Não. O inciso III exige reconhecimento, requerimento de encerramento e ausência de defesa/recurso.', 'Encerrar instância administrativa proíbe qualquer controle judicial? Não. Esgota o regime administrativo, sem revogar acesso à Justiça ou garantias constitucionais.', 'Encerramento administrativo','Fim da instância por hipótese legal, distinto de mera quitação ou de vedar Judiciário.',notes=['Integrar art. 284, §2º, que não considera pagamento ordinário renúncia automática.'])
add('290-a','Pedido de suspensão do prazo se baseia em força maior comprovada. Resposta: integrar a exceção legal e regulamento, sem suspensão por conveniência.', 'O regime específico de free flow de 2026 suspendeu prazos no recorte aprovado; não usar a regra geral para ignorar esse ato.', 'Feriado prolongado suspende automaticamente todo prazo pelo art. 290-A? Não. A exceção é força maior comprovada nos termos do regulamento, distinta de suspensão genérica por feriado.', 'O texto geral elimina qualquer regime transitório específico aprovado? Não. Deve ser integrado a hipóteses especiais vigentes e seus limites, como free flow em 2026.', 'Força maior comprovada','Fato excepcional demonstrado no regime pertinente, não simples preferência de prazo.',notes=['Distinguir suspensão e eventual prorrogação de vencimento em dia não útil. Não perpetuar transição do free flow após fim do prazo.'],sources=[D277])
add(291,'Lesão culposa ocorre em via de máxima 60, com velocidade 110 km/h no recorte apurado. Resposta: o §1º, III, trabalha com diferença de 50 km/h, não 50% do art. 218.', 'Não aplicar todos os institutos dos Juizados a lesão com álcool ou competição não autorizada; também não concluir que toda alternativa processual, inclusive ANPP, foi universalmente extinta pelo §1º.', 'O limiar do inciso III é percentual de 50%? Não. O texto usa CINQUENTA KM/H de excesso, distinto do percentual do art. 218.', 'As exceções do §1º afastam automaticamente todo instituto consensual de qualquer crime? Não. Delimitam arts. 74, 76 e 88 da Lei 9.099 na lesão culposa; outros regimes têm requisitos próprios.', 'Recorte dos Juizados','Aplicação dos dispositivos expressos, com exceções, distinta de toda negociação penal.',atencao=['A literalidade em 50 km/h não deve ser transformada em 50%; conferir velocidade apurada e enquadramento.','Nas exceções há inquérito do §2º. Não equiparar fato a homicídio doloso automaticamente por álcool ou velocidade.','Pena-base do §4º: diretrizes CP 59 e atenção a culpabilidade/circunstâncias/consequências, sem bis in idem.'],sources=[CPP])
add(292,'Motorista profissional é condenado por homicídio culposo no trânsito. Resposta: a condição profissional não impede por si a pena de suspensão, conforme Tema 486/STF.', 'Suspensão/proibição judicial pode ser isolada ou cumulada segundo regime, sem confundir com suspensão administrativa por pontos.', 'O exercício de profissão torna toda suspensão judicial inconstitucional? Não. Tema 486 reconheceu constitucional a pena ao profissional condenado por homicídio culposo, sem imunidade ocupacional.', 'O artigo manda aplicar sempre isoladamente a suspensão? Não. A redação admite aplicação isolada OU cumulativa com outras penalidades nos casos pertinentes.', 'Pena judicial de direção','Consequência criminal distinta do processo administrativo e da mera cautelar.',notes=['STF, RE 607107, julgamento de 12/2/2020: Tema 486 no recorte de homicídio culposo; não universalizar a toda controvérsia profissional.'],sources=[STF486])
add(293,'Após trânsito em julgado, o réu é intimado a entregar documento. Resposta: prazo de 48 horas da intimação pertinente, não automaticamente do conhecimento informal da sentença.', 'A duração da pena criminal de dois meses a cinco anos é distinta das faixas de suspensão administrativa do art. 261.', 'O termo das 48 horas dispensa intimação porque já houve trânsito em julgado? Não. O §1º prevê que o réu será INTIMADO a entregar, mantendo o marco procedimental.', 'A pena criminal de direção corre automaticamente enquanto recolhido por condenação penal? Não. O §2º estabelece que não se inicia nesse recolhimento; observar a hipótese e execução.', 'Entrega intimada','Dever de entrega no marco judicial próprio, distinto de prazo de medida administrativa.',notes=['Não contar prazo criminal de toda prisão cautelar como se o §2º descrevesse qualquer custódia sem recorte.'])
add(294,'O MP requer suspensão cautelar e o juiz fundamenta necessidade concreta de ordem pública. Resposta: examinar adequação e pressupostos, sem exigir condenação definitiva para toda cautelar.', 'A expressão de ofício ainda transcrita precisa de integração ao CPP 282, §2º, e sistema acusatório; não criar exercício de iniciativa judicial irrestrita.', 'A cautelar exige sempre trânsito em julgado para existir? Não. O artigo alcança investigação/ação, com necessidade, motivação e integração processual; não confundir com pena definitiva.', 'Recurso do parágrafo possui efeito suspensivo automático? Não. Prevê recurso em sentido estrito SEM efeito suspensivo para as decisões descritas.', 'Cautelar de direção','Medida processual motivada, distinta da pena após condenação definitiva.',simples='Suspensão/proibição cautelar exige necessidade para ordem pública e decisão motivada na fase pertinente, distinta da pena definitiva. O texto menciona de ofício, MP e representação policial; essa iniciativa deve ser confrontada com CPP 282, §2º, e sistema acusatório atual, sem ensinar atuação de ofício irrestrita. Recurso em sentido estrito do parágrafo não tem efeito suspensivo.',atencao=['Não copiar a expressão histórica de ofício como autorização atual universal sem compatibilidade processual e jurisprudência.','Não certificada aqui solução específica de todos os conflitos entre norma especial e CPP; exemplos usam requerimento do MP e requisitos não controvertidos.','Medida deve ser fundamentada por elementos concretos, não gravidade abstrata ou suspensão automática pelo flagrante.'],sources=[CPP])
add(295,'A autoridade judicial determina suspensão/proibição no processo. Resposta: comunica ao Contran e ao órgão estadual do domicílio/residência do indiciado/réu conforme artigo.', 'Essa comunicação não atribui ao Contran o julgamento da ação penal nem elimina o procedimento judicial que fundamentou a medida.', 'A comunicação é facultativa por conveniência do juízo? Não. O texto usa SEMPRE e indica ambos os destinatários no recorte legal.', 'Comunicar a pena a órgão administrativo transforma-o em juiz do delito? Não. Execução/registro da comunicação e competência penal são funções distintas.', 'Comunicação judicial','Notícia obrigatória aos destinatários legais, distinta da decisão de mérito penal.',notes=['Integrar procedimentos atuais de registro sem substituir silenciosamente o destinatário que o texto legal nomeia.'])
